package com.pipeline.pulse.domain;

import org.hibernate.annotations.IdGeneratorType;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * Marks a String identifier that is supplied by the client when present, and otherwise
 * generated by PostgreSQL via {@code gen_random_uuid()} and stored in text form.
 */
@IdGeneratorType(PostgresTextIdGenerator.class)
@Retention(RetentionPolicy.RUNTIME)
@Target({ElementType.FIELD, ElementType.METHOD})
public @interface PostgresTextId {
}
